<template>
  <div class="item-loan">
    <table
      v-if="customerLoans.length > 0"
      class="table table-sm table-hover table-stripped mt-1"
    >
      <thead>
        <tr style="font-size: 12pt" class="bg-secondary text-white">
          <th>Ordem</th>
          <td>Data De Submissão</td>
          <td>Nº Prestações</td>
          <td>Taxa De Juros</td>
          <td>Montante</td>
          <td>Estado Do Crédito</td>
          <td class="text-center">Acções</td>
        </tr>
      </thead>
      <tbody>
        <tr
          style="font-size: 12pt"
          v-for="(loan, index) in customerLoans"
          :key="index"
        >
          <td>{{ index + 1 }}</td>
          <td v-date-format="loan.dateCreated"></td>
          <td>{{ loan.numberOfInstallments }}</td>
          <td>{{ loan.interestRate * 100 }}%</td>
          <td v-money-format="loan.amount"></td>
          <td>{{ getLoanStatus(loan.status) }}</td>
          <td v-if="loan.status > -1">
            <b-row class="text-center">
              <b-col>
                <b-badge
                  v-if="loan.status > 0"
                  @click="getLoanAmortization(loan)"
                  variant="primary"
                  pill
                  style="cursor: pointer; font-size: 12pt"
                  ><b-icon icon="eye-fill" aria-hidden="true"></b-icon>
                  Transações</b-badge
                >
                <b-badge
                  v-else
                  @click="deleteLoan(loan)"
                  variant="danger"
                  pill
                  style="cursor: pointer; font-size: 12pt"
                  ><b-icon icon="trash-fill" aria-hidden="true"></b-icon>
                  Deletar</b-badge
                >
              </b-col>
              <b-col
                ><b-badge
                  @click="previewLoan(loan)"
                  variant="secondary"
                  pill
                  style="cursor: pointer; font-size: 12pt"
                  ><b-icon icon="image" aria-hidden="true"></b-icon>
                  Garantias
                </b-badge>
              </b-col>
              <b-col
                ><b-badge
                  variant="secondary"
                  pill
                  style="cursor: pointer; font-size: 12pt"
                  @click="getAmortizationLoans(loan, true)"
                >
                  <b-icon icon="download" aria-hidden="true"></b-icon>
                  Contrato
                </b-badge>
              </b-col>
            </b-row>
          </td>
          <td v-else class="text-right">
            <b-badge
              variant="danger"
              pill
              style="cursor: pointer; font-size: 12pt"
              ><b-icon icon="xl" aria-hidden="true"></b-icon> Financiamento
              rejeitado</b-badge
            >
          </td>
        </tr>
      </tbody>
    </table>

    <b-modal
      hide-footer
      ref="preview-loan"
      title="Bens Apresentados Como Garantia"
      size="xl"
    >
      <b-overlay :show="isLoading" rounded="sm">
        <div v-if="currentLoan.status == 0">
          <b-row>
            <b-col></b-col>
            <b-col lg="8">
              <b-form-group
                label-for="textarea-formatter"
                class="mb-0 text-center"
                style="font-weight: bold; font-size: 12pt"
              >
                <b-form-textarea
                  class="text-center"
                  id="textarea-formatter"
                  v-model="form.guaranteeDescription"
                  placeholder="Descrição da garantia"
                ></b-form-textarea>
              </b-form-group>
            </b-col>
            <b-col></b-col>
          </b-row>
          <b-row>
            <b-col>
              <b-input-group size="sm" class="mt-1">
                <b-input-group-prepend is-text>
                  <b>Preço estimado - MZN</b>
                </b-input-group-prepend>
                <b-form-input
                  type="number"
                  step="any"
                  min="100"
                  size="sm"
                  v-model="form.purchaseAmount"
                  placeholder="Montante"
                ></b-form-input> </b-input-group
            ></b-col>
            <b-col
              ><b-form-file
                accept="*"
                @change="onFileChange"
                class="mt-2 mb-2"
                size="sm"
              ></b-form-file
            ></b-col>
            <b-col cols="2">
              <b-button
                :disabled="
                  isLoading ||
                  uploadValue > 0 ||
                  !selectedFile ||
                  !form.guaranteeDescription
                "
                type="submit"
                size="sm"
                variant="success"
                @click="onUploadFile()"
                class="mt-2 mb-2"
                block
                >Gravar <b-icon icon="cloud-upload-fill" font-scale="1"></b-icon
              ></b-button>
            </b-col>
          </b-row>
          <b-row>
            <b-col class="text-center" cols="12">
              <b-progress
                :value="uploadValue"
                :max="100"
                show-progress
                animated
                class="mt-1 mb-1"
                v-if="uploadValue > 0"
              ></b-progress>
            </b-col>
          </b-row>
        </div>
        <table
          v-if="loanGuarantees.length > 0"
          class="table table-sm table-hover table-stripped mt-1"
        >
          <thead>
            <tr style="font-size: 12pt; font-weight: bold">
              <th>#</th>
              <td colspan="2">Descrição da Garantia</td>
              <td class="text-right">Valor estimado</td>
              <td class="text-center">Acções</td>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="(guarantee, index) in loanGuarantees"
              :key="guarantee.id"
              style="font-size: 12pt"
            >
              <th>{{ index + 1 }}</th>
              <td colspan="2">{{ guarantee.guaranteeDescription }}</td>
              <td
                class="text-right"
                v-money-format="guarantee.purchaseAmount"
              ></td>
              <td>
                <b-row>
                  <b-col
                    class="text-right"
                    @click="deleteGuarantee(guarantee.id)"
                    ><b-badge
                      variant="danger"
                      pill
                      style="cursor: pointer; font-size: 12pt"
                      ><b-icon icon="trash-fill" aria-hidden="true"></b-icon>
                      Deletar</b-badge
                    ></b-col
                  >
                  <b-col class="text-right"
                    ><b-badge
                      variant="secondary"
                      pill
                      style="cursor: pointer; font-size: 12pt"
                      ><b-icon icon="pen" aria-hidden="true"></b-icon>
                      Editar</b-badge
                    ></b-col
                  >
                </b-row>
              </td>
            </tr>
            <tr style="cursor: pointer; font-size: 12pt">
              <th colspan="4">Valor total das garantias</th>
              <th class="text-right" v-money-format="totalGuaranteeAmount"></th>
            </tr>
            <tr style="cursor: pointer; font-size: 12pt">
              <th colspan="4">
                Crédito solicitado + Juros de
                {{ currentLoan.interestRate * 100 }}%
              </th>
              <th
                class="text-right"
                v-money-format="totalAmount(currentLoan)"
              ></th>
            </tr>
          </tbody>
        </table>
        <b-alert
          show
          dismissible
          variant="danger"
          class="text-center"
          v-if="totalGuaranteeAmount < totalAmount(currentLoan)"
        >
          <b-icon icon="exclamation-circle-fill" variant="danger"></b-icon>
          Garantias insuficientes!
        </b-alert>
        <b-row>
          <b-col cols="3"
            ><b-button
              type="submit"
              size="sm"
              variant="secondary"
              @click="openGuaranteesSlide()"
              class="mt-2 mb-2"
              block
              >Fotos de garantia
              <b-icon icon="image" font-scale="1"></b-icon></b-button
          ></b-col>
          <b-col cols="3"
            ><b-button
              type="submit"
              size="sm"
              variant="primary"
              @click="printLoanGuarantees()"
              class="mt-2 mb-2"
              block
              >Declaração
              <b-icon icon="download" font-scale="1"></b-icon></b-button
          ></b-col>
          <b-col v-if="checkElegibility(currentLoan)">
            <b-form-datepicker
              placeholder="Data de desembolso"
              block
              size="sm"
              id="from-datepicker"
              v-model="dueDate"
            ></b-form-datepicker>
          </b-col>
          <b-col cols="3">
            <b-button
              v-if="checkElegibility(currentLoan)"
              type="submit"
              size="sm"
              variant="success"
              :disabled="user.userRole != 1 || currentLoan.status > 0"
              @click="approveLoan()"
              class="mt-2 mb-2"
              block
              >Aprovar Crédito <b-icon icon="save2" font-scale="1"></b-icon
            ></b-button>
            <b-button
              v-else
              type="submit"
              size="sm"
              variant="danger"
              :disabled="user.userRole != 1"
              @click="rejectLoan(currentLoan)"
              class="mt-2 mb-2"
              block
              >Rejeitar Crédito <b-icon icon="x-lg" font-scale="1"></b-icon
            ></b-button>
          </b-col>
        </b-row>
      </b-overlay>
    </b-modal>

    <b-modal hide-footer ref="delete-loan" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir este financiamento?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Excluir</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal hide-footer ref="delete-guarantee" title="Deletar">
      <p class="text-danger text-center">
        {{
          currentLoan.status > 0
            ? "Não tem permissão de excluir esta garantia"
            : "Deseja realmente excluir esta garantia?"
        }}
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletionGuarantee()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button
            :disabled="currentLoan.status > 0"
            block
            size="sm"
            variant="danger"
            @click="decidedToDeleteGuarantee()"
            >Excluir</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal
      hide-footer
      ref="show-guarantees"
      class="text-center"
      title="Bens de garantia"
    >
      <b-carousel
        id="carousel-fade"
        style="text-shadow: 0px 0px 2px #000"
        fade
        indicators
        img-width="512"
        img-height="240"
      >
        <b-carousel-slide
          v-for="photo in loanGuarantees"
          :key="photo.id"
          :caption="convertMoney(photo.purchaseAmount)"
          :img-src="photo.guaranteeFileUrl"
        ></b-carousel-slide>
      </b-carousel>
    </b-modal>

    <b-modal
      hide-footer
      ref="loan-payment"
      title="Plano De Amortização"
      size="xl"
    >
      <AmortizationPlan :current-loan="currentLoan" />
    </b-modal>
  </div>
</template>
<script>
import { mapGetters } from "vuex";
import MoneyFormat from "@/utils/moneyFormat";
import companyLogo from "@/utils/companyLogo";
import nthusoStamp from "@/utils/nthusoStamp";
import firebase from "firebase";
import logs from "@/utils/logs";
import AmortizationPlan from "./AmortizationPlan.vue";
import axios from "axios";
import moment from "moment";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import AmmortizationPlan from "@/utils/amortizationPlan";
import DateFormat from "@/utils/dateFormat";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "item-loan",

  components: {
    AmortizationPlan,
  },

  data: () => ({
    form: {
      guaranteeDescription: "",
      guaranteeFileUrl: "",
      purchaseAmount: 0,
      status: 0,
    },

    dueDate: "",
    selectedFile: "",
    uploadValue: 0,

    customerLoanAmortization: [],
    loanGuarantees: [],
    today: moment(),
    currentLoan: 0,
    guaranteeId: 0,
    totalGuaranteeAmount: 0,
  }),

  created() {},

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "currentCustomer",
      "customerLoans",
      "customerTranzactions",
      "company",
    ]),
  },

  methods: {
    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    convertGender() {
      return this.currentCustomer.sex == "M" ? "MUTUÁRIO" : "MUTUÁRIA";
    },

    convertA() {
      return this.currentCustomer.sex == "M" ? "o" : "a";
    },

    totalAmount(loan) {
      return loan.amount * loan.interestRate + loan.amount;
    },

    checkElegibility(loan) {
      const elegibility = loan.amount * loan.interestRate + loan.amount;
      return this.totalGuaranteeAmount >= elegibility ? true : false;
    },

    openGuaranteesSlide() {
      this.$refs["show-guarantees"].show();
    },

    deleteLoan(loan) {
      this.loanId = loan.id;
      this.$refs["delete-loan"].show();
    },

    deleteGuarantee(id) {
      this.guaranteeId = id;
      this.$refs["delete-guarantee"].show();
    },

    getLoanStatus(status) {
      if (status == 0) {
        return "Em processamento";
      } else if (status == -1) {
        return "Rejeitado";
      } else if (status == 1) {
        return "Desembolsado";
      } else if (status == 2) {
        return "Saneado";
      } else if (status == 3) {
        return "Terminado";
      }
    },

    cancelDeletion() {
      this.$refs["delete-loan"].hide();
    },

    cancelDeletionGuarantee() {
      this.$refs["delete-guarantee"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/loan/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getCustomerLoans();
            this.$refs["delete-loan"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-loan"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-loan"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    decidedToDeleteGuarantee() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/deleteGuarantee/${this.guaranteeId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getLoanGuarantees(false);
            this.$refs["delete-guarantee"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-guarantee"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        });
    },

    getCustomerLoans() {
      this.$store.dispatch(
        "getCustomerLoans",
        this.currentCustomer.accountNumber
      );
    },

    previewLoan(loan) {
      this.currentLoan = loan;
      this.getLoanGuarantees(false);
      this.$refs["preview-loan"].show();
    },

    onFileChange(e) {
      this.selectedFile = e.target.files[0];
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    printContrat(loan) {
      const ammortizationPlan = AmmortizationPlan.getAmmortization(
        this.customerLoanAmortization
      );

      const loanGuarantees = AmmortizationPlan.getLoanGuarantees(
        this.loanGuarantees
      );

      let docDefinition = {
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 7,
              margin: [30, 0, 0, 0],
            },
            {
              text: this.company.smsSender,
              alignment: "right",
              fontSize: 7,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        // header: {
        //   columns: [
        //     {
        //       image: companyLogo.getLogo(),
        //       width: 100,
        //     },
        //     {
        //       text: `
        //         ${this.company.companyAddress}\n
        //         Telefone: +${this.company.companyPhone} | E-mail: ${this.company.companyEmail} | Website: ${this.company.companyWebsite} | NUIT: ${this.company.companyNuit}
        //         `,
        //       fontSize: 7,
        //       alignment: "center",
        //     },
        //   ],
        // },

        content: [
          {
            columns: [
              {
                image: companyLogo.getLogo(),
                width: 125,
              },
              {
                text: `
                ${this.company.companyAddress}\n
                Telefone: +${this.company.companyPhone} | E-mail: ${this.company.companyEmail} | Website: ${this.company.companyWebsite} | NUIT: ${this.company.companyNuit}
                `,
                fontSize: 7,
                alignment: "center",
              },
            ],
          },
          {
            text: "CONTRATO DE CONCESSÃO DE EMPRÉSTIMO",
            fontSize: 10,
            alignment: "center",
            bold: true,
          },
          {
            text: "\nEntre:\n\n",
            fontSize: 8,
            bold: true,
          },
          {
            text: {
              alignment: "justify",
              fontSize: 8,
              text: `${this.company.companyName}, representada pelo Director Geral, Sr ${this.company.companyManager}, com sede no ${this.company.companyAddress}, de ora em diante denominado de MUTUANTE.`,
            },
          },
          {
            text: `\n&\n\n`,
            fontSize: 8,
          },
          {
            text: {
              alignment: "justify",
              fontSize: 8,
              text: `${
                this.currentCustomer.customerName
              }, portador do B.I número ${
                this.currentCustomer.customerNationalId
              }, emitido em ${moment(this.currentCustomer.issuedAt).format(
                "DD/MM/YYYY"
              )} pela Direcção Nacional de Identificação Civil da Cidade de ${
                this.currentCustomer.localOfIssue
              }, residente no ${
                this.currentCustomer.customerAddress
              }, de ora em diante denominado de ${this.convertGender()}.`,
            },
          },
          {
            text: `\nÉ celebrado um contrato de crédito cujo o teor é reciprocamente aceites por ambas partes nos termos e condições que constam a seguir:`,
            fontSize: 8,
          },
          { text: "\n1. Montante\n", fontSize: 10, bold: true },
          {
            text: `A ${this.company.companyName}, concede a Sr ${
              this.currentCustomer.customerName
            }, um empréstimo no valor de ${this.convertMoney(
              loan.amount
            )} (${MoneyFormat.spellNumbers(
              loan.amount
            )} meticais), quantia a qual ${this.convertA()} ${this.convertGender()} se confessa devedor da mesma.`,
            bold: false,
            fontSize: 8,
          },
          {
            text: "\n2. Prazo e plano de pagamento\n",
            fontSize: 10,
            bold: true,
          },
          {
            type: "lower-roman",
            fontSize: 8,
            ol: [
              {
                text: `O presente empréstimo, é concedido por um período de 1 mês, em ${
                  loan.numberOfInstallments
                } ${
                  loan.numberOfInstallments == 1 ? " prestação" : " prestações"
                }, tendo como data de vencimento ${this.getDueDate(
                  this.customerLoanAmortization
                )}.`,
                bold: false,
              },
              {
                text: `O pagamento das prestações será feito à boca de caixa da empresa ou por depósito e transferência em uma das contas bancárias ou carteiras móveis da ${this.company.companyName}.`,
                bold: false,
              },
              {
                text: `Em caso de mora no pagamento da prestação, ou outros encargos, cobra-se uma taxa fixa diária de ${
                  this.company.forfeit * 100
                }% sobre os respectivos montantes a partir do momento do vencimento do prazo até o seu pagamento.`,
                bold: false,
              },
              {
                text: `Cabe ao Mutuante decidir a data limite para pôr termo a contagem de juros de mora e proceder com cobrança e ou execução dos bens do valor em causa.`,
                bold: false,
              },
              {
                text: `Ao fim de 30 dias, ${this.convertA()} ${this.convertGender()} fará a devolução do valor acrescido de uma taxa de juros de ${
                  loan.interestRate * 100
                }% sobre o valor do crédito`,
                bold: false,
              },
              {
                text: `O Mutuário fará a devolução no valor de ${this.convertMoney(
                  loan.amount * loan.interestRate + loan.amount
                )} (${MoneyFormat.spellNumbers(
                  loan.amount * loan.interestRate + loan.amount
                )} meticais), sendo que ${this.convertA()} ${this.convertGender()} irá devolver o valor mutuado em ${
                  loan.numberOfInstallments
                } ${
                  loan.numberOfInstallments == 1 ? " prestação" : " prestações"
                } designadamente:`,
                bold: false,
              },
            ],
          },
          {
            table: {
              widths: ["auto", "*", "auto", "auto", "auto"],
              body: [
                [
                  { text: "Ordem", style: "columnsTitle" },
                  { text: "Data de vencimento", style: "columnsTitle" },
                  { text: "Capital", style: "columnsTitle" },
                  {
                    text: `Juros (${this.currentLoan.interestRate * 100}%)`,
                    style: "columnsTitle",
                  },
                  { text: "Valor da prestação", style: "columnsTitle" },
                ],
                ...ammortizationPlan,
              ],
            },
            layout: "lightHorizontalLines",
          },
          { text: "\n3. Declaração de penhora\n", fontSize: 10, bold: true },
          {
            text: `1. De modo a assegurar o reembolso do capital, juros e despesas que o Mutuante tenha relacionados ao empréstimo, ao ${this.convertGender()} obriga-se a penhorar os seguintes bens:`,
            bold: false,
            fontSize: 8,
          },
          {
            type: "lower-roman",
            fontSize: 8,
            ol: loanGuarantees,
          },
          {
            text: `\n2. No incumprimento das suas obrigações, a instituição reserva-se o direito de se fazer pagar pelas garantias assumidas, devendo ${this.convertA()} ${this.convertGender()} entregar voluntariamente os bens acima referidos, logo que for comunicado.\n`,
            bold: false,
            fontSize: 8,
          },
          { text: "\n4. Foro\n", fontSize: 10, bold: true },
          {
            type: "lower-roman",
            fontSize: 8,
            ol: [
              {
                text: `Convenciona-se que no caso de litigio, o foro será o Tribunal Juducial da Cidade de Maputo.`,
                bold: false,
              },
              {
                text: `As dúvidas e omissões serão resolvidas, em primeira instância amigavelmente. Na falta de concenso, por recurso a Lei Comercial vigente e demais legislações aplicáveis.`,
                bold: false,
              },
            ],
          },
          { text: "\n\n\n" },
          {
            text: `Maputo, aos ${DateFormat.formatDate(
              this.currentLoan.updatedAt
            )}`,
            bold: false,
            fontSize: 8,
            alignment: "center",
          },
          { text: "\n\n\n" },
          {
            alignment: "center",
            fontSize: 8,
            columns: [
              {
                image: nthusoStamp.getStamp(),
                width: 120,
              },
              {},
              {
                text: `__________________________\n\n${
                  this.currentCustomer.customerName
